#include "hip_api.h"
using namespace hip_probe;
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("gold MODULE INPUT OUT");std::ifstream f(argv[2],std::ios::binary|std::ios::ate);if(!f||f.tellg()!=1966080)throw std::runtime_error("QKV byte extent");std::vector<unsigned char>v(1966080);f.seekg(0);f.read((char*)v.data(),v.size());unsigned stride=1024,base=(2*640+16)*1024+7*32;for(unsigned l=0;l<32;l++)if((base+((l/8)*4+(l&3))*stride+((l&4)?8:0))%8)throw std::runtime_error("unaligned address");Api a(7);a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");Handle m{},q{},fn{};void *di{},*out{};a.Check(a.LoadModule(&m,argv[1]),"module");a.Check(a.hipStreamCreate(&q),"stream");a.Check(a.hipModuleGetFunction(&fn,m,"tr_b64_probe"),"function");a.Check(a.hipMalloc(&di,v.size()),"input");a.Check(a.hipMalloc(&out,1024),"output");a.Check(a.hipMemcpy(di,v.data(),v.size(),1),"upload");void*args[]={&di,&out,&stride,&base};a.Check(a.hipModuleLaunchKernel(fn,1,1,1,32,1,1,0,q,args,nullptr),"fullwave launch");a.Check(a.hipStreamSynchronize(q),"completion");std::vector<unsigned>w(256);a.Check(a.hipMemcpy(w.data(),out,1024,2),"read");std::ofstream(argv[3],std::ios::binary).write((char*)w.data(),1024);size_t olddiff=0,trdiff=0;for(unsigned l=0;l<32;l++)for(unsigned c=0;c<2;c++)for(unsigned e=0;e<8;e++){unsigned expected=v[base+(l/16*8+e)*stride+c*16+l%16],old=(w[l*8+c*2+e/4]>>(8*(e%4)))&255,tr=(w[l*8+4+c*2+e/4]>>(8*(e%4)))&255;olddiff+=old!=expected;trdiff+=tr!=expected;}printf("TR_B64_BYTE_GOLD lanes=32 channels=32 tokens=16 stride=1024 base=%u alignment=8 fullwave=1 old_CPU_byte_diff=%zu tr_CPU_byte_diff=%zu\n",base,olddiff,trdiff);a.hipFree(out);a.hipFree(di);a.hipStreamDestroy(q);a.hipModuleUnload(m);if(olddiff||trdiff)throw std::runtime_error("fragment byte mismatch");return 0;}catch(const std::exception&e){fprintf(stderr,"BYTE_GOLD_FAIL %s\n",e.what());return 1;}}
